changeSet.sql:
DO $enum$
BEGIN
    IF to_regtype('invoice_type') IS NULL THEN
        CREATE TYPE invoice_type AS ENUM ('ARRIVAL', 'SHIPMENT', 'SALE', 'RETURN_FROM_CUSTOMER', 'RETURN_TO_SUPPLIER');
    END IF;
    IF to_regtype('invoice_status') IS NULL THEN
        CREATE TYPE invoice_status AS ENUM ('DRAFT', 'CONFIRMED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'WAIT');
    END IF;
    IF to_regtype('user_role') IS NULL THEN
        CREATE TYPE user_role AS ENUM ('ADMIN', 'WAREHOUSE_MANAGER', 'STORE_MANAGER');
    END IF;
END
$enum$;

ALTER TYPE invoice_type ADD VALUE IF NOT EXISTS 'ARRIVAL';
ALTER TYPE invoice_type ADD VALUE IF NOT EXISTS 'SHIPMENT';
ALTER TYPE invoice_type ADD VALUE IF NOT EXISTS 'SALE';
ALTER TYPE invoice_type ADD VALUE IF NOT EXISTS 'RETURN_FROM_CUSTOMER';
ALTER TYPE invoice_type ADD VALUE IF NOT EXISTS 'RETURN_TO_SUPPLIER';
ALTER TYPE invoice_status ADD VALUE IF NOT EXISTS 'DRAFT';
ALTER TYPE invoice_status ADD VALUE IF NOT EXISTS 'CONFIRMED';
ALTER TYPE invoice_status ADD VALUE IF NOT EXISTS 'IN_PROGRESS';
ALTER TYPE invoice_status ADD VALUE IF NOT EXISTS 'COMPLETED';
ALTER TYPE invoice_status ADD VALUE IF NOT EXISTS 'CANCELLED';
ALTER TYPE invoice_status ADD VALUE IF NOT EXISTS 'WAIT';
ALTER TYPE user_role ADD VALUE IF NOT EXISTS 'ADMIN';
ALTER TYPE user_role ADD VALUE IF NOT EXISTS 'WAREHOUSE_MANAGER';
ALTER TYPE user_role ADD VALUE IF NOT EXISTS 'STORE_MANAGER';
